MATCH (acc:FlightAccident)-[:involves]->(model:AircraftModel)
WHERE acc.date STARTS WITH '2015' AND (acc.location = 'Juba' OR acc.name CONTAINS 'Juba')
RETURN model.name AS aircraft_name, model.length_metre AS length_metre;

MATCH (flight:FlightAccident)-[:departsFrom]->(airport:Airport)
WHERE flight.name IN ["Sriwijaya Air Flight 182", "Adam Air Flight 574"]
RETURN DISTINCT airport.name AS airport_name;

MATCH (fa:FlightAccident)
WHERE EXISTS { MATCH (fa)-[:departsFrom]->(:Airport {name: 'Stockholm Arlanda Airport'}) }
   OR EXISTS { MATCH (fa)-[:involves]->(:AircraftModel {name: 'McDonnell Douglas MD-81'}) }
RETURN count(DISTINCT fa) AS accident_count

// Aircraft models produced by LET Aircraft Industries (any direction of :manufacturedBy)
MATCH (m:AircraftManufacturer {name: "LET Aircraft Industries"})
MATCH (model:AircraftModel)-[:manufacturedBy]-(m)
RETURN model.name AS model_name
UNION
// Aircraft models involved in the specified accident (any direction of :involves)
MATCH (acc:FlightAccident {name: "Parachute Kemerovo Let L-410UVP-E"})
MATCH (model:AircraftModel)-[:involves]-(acc)
RETURN model.name AS model_name
ORDER BY model_name;
